CREATE OR REPLACE PROCEDURE sp(
    para_dribbling NUMBER,
    para_player_fifa_api_id NUMBER,
    para_long_shots NUMBER,
    para_sliding_tackle NUMBER
) IS
    v_count NUMBER;
    v_dummy NUMBER;
    v_long_shots NUMBER;
    v_new_sliding_tackle NUMBER;

    CURSOR c1 IS
        SELECT id
        FROM Player_Attributes
        WHERE dribbling = para_dribbling
          AND player_fifa_api_id = para_player_fifa_api_id
        FOR UPDATE;

    CURSOR c2 IS
        SELECT long_shots
        FROM Player_Attributes
        WHERE sliding_tackle IS NULL OR sliding_tackle = 0
        FOR UPDATE;
BEGIN
    SELECT COUNT(*)
    INTO v_count
    FROM Player_Attributes
    WHERE dribbling = para_dribbling
      AND player_fifa_api_id = para_player_fifa_api_id;

    IF v_count > 0 THEN
        OPEN c1;
        LOOP
            FETCH c1 INTO v_dummy;
            EXIT WHEN c1%NOTFOUND;
            UPDATE Player_Attributes
            SET long_shots = para_long_shots
            WHERE CURRENT OF c1;
        END LOOP;
        CLOSE c1;
    ELSE
        INSERT INTO Player_Attributes (dribbling, player_fifa_api_id, long_shots)
        VALUES (para_dribbling, para_player_fifa_api_id, para_long_shots);
    END IF;

    OPEN c2;
    LOOP
        FETCH c2 INTO v_long_shots;
        EXIT WHEN c2%NOTFOUND;
        IF v_long_shots IS NOT NULL AND v_long_shots <> 0 THEN
            v_new_sliding_tackle := v_long_shots;
        ELSE
            v_new_sliding_tackle := para_sliding_tackle;
        END IF;
        UPDATE Player_Attributes
        SET sliding_tackle = v_new_sliding_tackle
        WHERE CURRENT OF c2;
    END LOOP;
    CLOSE c2;
END sp;

